import {analyzeTrack} from './analysis.js?v=20261007-online';
import {validateExport,trackSlug} from './ac-export.js?v=20261007-online';

const $=s=>document.querySelector(s),num=(n,d=0)=>Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function metric(label,value,unit=''){const node=document.createElement('div');node.className='analysis-metric';const l=document.createElement('span'),v=document.createElement('strong'),u=document.createElement('small');l.textContent=label;v.textContent=value;u.textContent=unit;v.append(u);node.append(l,v);return node;}
function profile(rows){
  if(!rows.length)return '<p class="field-hint">Add road points to see the elevation profile.</p>';
  const low=Math.min(...rows.map(r=>r.elevation)),high=Math.max(...rows.map(r=>r.elevation)),range=Math.max(1,high-low),length=rows[rows.length-1].distance||1;
  const points=rows.map(r=>`${24+r.distance/length*572},${102-(r.elevation-low)/range*72}`).join(' '),firstY=102-(rows[0].elevation-low)/range*72,lastY=102-(rows[rows.length-1].elevation-low)/range*72;
  return `<svg viewBox="0 0 620 145" role="img" aria-label="Hand-authored elevation profile, ${num(low,1)} to ${num(high,1)} meters"><line x1="24" y1="30" x2="596" y2="30" stroke="#d8e0d0" stroke-dasharray="3 4"/><line x1="24" y1="102" x2="596" y2="102" stroke="#d8e0d0"/><polygon points="24,112 24,${firstY} ${points} 596,${lastY} 596,112" fill="#dce8d4"/><polyline points="${points}" stroke="#62835b" stroke-width="2" fill="none"/><text x="24" y="21">${num(high,1)} m</text><text x="24" y="135">0 m</text><text x="596" y="135" text-anchor="end">${num(length)} m</text></svg>`;
}
export function mountAnalysis(api){
  const panel=document.createElement('section');panel.className='panel-section analysis-summary';panel.innerHTML='<div class="section-heading"><span class="section-num">DATA</span><h2>Circuit insights</h2><span id="analysis-ready" class="analysis-badge">Draft</span></div><div id="analysis-summary-metrics" class="analysis-metrics"></div><p id="analysis-scale-note" class="field-hint"></p><div class="analysis-actions"><button id="open-analysis" class="outline-button">Full analysis ↗</button><button id="reverse-circuit" class="outline-button">Reverse direction</button></div><label class="toggle-row"><span>Show corner analysis on map</span><input type="checkbox" id="analysis-overlay"><span class="toggle"></span></label>';
  $('.settings-panel').prepend(panel);
  const button=document.createElement('button');button.id='analysis-mode';button.textContent='Analyze';$('.mode-switch').append(button);
  const dialog=document.createElement('dialog');dialog.id='analysis-dialog';dialog.className='tracer-dialog analysis-dialog';dialog.innerHTML='<div class="dialog-top"><p class="eyebrow">GEOMETRY / LIVE DATA</p><button id="close-analysis" class="icon-button" aria-label="Close analysis">×</button></div><h2 id="analysis-name"></h2><p id="analysis-status" class="dialog-description"></p><div id="analysis-full-metrics" class="analysis-metrics full-metrics"></div><div class="analysis-section"><div class="analysis-section-heading"><h3>Elevation profile</h3><span>Hand-authored heights</span></div><div id="elevation-profile" class="elevation-profile"></div></div><div class="analysis-columns"><section><h3>Export readiness</h3><div id="analysis-checks"></div><button id="use-pit-capacity" class="outline-button" hidden>Use estimated pit capacity</button></section><section><h3>Circuit profile</h3><div id="analysis-profile-data"></div><button id="edit-analysis-details" class="outline-button">Edit circuit details</button></section></div><section class="analysis-section"><div class="analysis-section-heading"><h3>Corner inventory</h3><span>Click a row to locate it</span></div><div id="analysis-corners" class="corner-inventory"></div><p class="field-hint">Geometric bend estimates from the traced centerline. Counts depend on smoothing, road width, and scale.</p></section><details class="analysis-method"><summary>How these numbers are calculated</summary><p>Length follows the scaled centerline. Approximate paved area is length × width, excluding pits and kerbs. Bends are grouped by curvature and turning angle; straights use a radius threshold. Heights are authored by you. Pit bays use the generated layout, with a connected parking apron for short routes. Inspect placement in 3D.</p><p>These are geometry estimates. They do not predict lap times or certify Assetto Corsa compatibility.</p></details><div class="dialog-actions"><button id="analysis-json" class="outline-button">Download report JSON</button><button id="analysis-csv" class="outline-button">Download samples CSV</button><button id="analysis-inspect" class="primary-button">Inspect in 3D</button></div>';
  document.body.append(dialog);$('#close-analysis').onclick=()=>dialog.close();
  dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
  let current=null,lastKey='',timer;
  function report(){const t=api.getTrack();return {...analyzeTrack(t),generatedAt:new Date().toISOString(),profile:{...t.details,creator:t.export?.author,country:t.export?.country,city:t.export?.city},exportReadiness:validateExport(t)};}
  function render(){
    const t=api.getTrack(),data=report(),m=data.metrics,check=data.exportReadiness;current=data;api.onAnalysis(data);
    const ready=!check.errors.length;$('#analysis-ready').textContent=ready?'Export ready':t.complete===false?'Open road':`${check.errors.length} to fix`;$('#analysis-ready').classList.toggle('ready',ready);
    const summary=$('#analysis-summary-metrics');summary.replaceChildren(metric('Length',num(m.lengthMeters),'m'),metric('Bends',String(m.corners)),metric('Elevation range',num(m.elevationRangeMeters,1),'m'),metric('Longest straight',num(m.longestStraightMeters),'m'));
    $('#analysis-scale-note').textContent=`${data.scale.source==='map'?'Satellite scale':data.scale.source==='calibrated'?'Two-point calibration':'Manual scale'} · ${num(data.scale.metersPerPixel,4)} m/px · ${m.direction}`;
    $('#reverse-circuit').disabled=t.points.length<2;$('#analysis-overlay').checked=api.getOverlay();
    $('#analysis-name').textContent=t.name;$('#analysis-status').textContent=`${t.complete===false?'Open road':'Closed, editable circuit'} · ${m.direction} · ${t.points.length} control points`;
    const full=$('#analysis-full-metrics');full.replaceChildren(metric('Centerline length',num(m.lengthMeters,1),'m'),metric('3D path length',num(m.surfaceLengthMeters,1),'m'),metric('Road width',num(m.widthMeters,1),'m'),metric('Approx. paved area',num(m.pavedAreaSquareMeters),'m²'),metric('Left / right bends',`${m.leftCorners} / ${m.rightCorners}`),metric('Tightest radius',num(m.minRadiusMeters,1),'m'),metric('Longest straight',num(m.longestStraightMeters,1),'m'),metric('Max. slope',num(m.maxGradePercent,1),'%'),metric('Total climb',num(m.climbMeters,1),'m'),metric('Maximum banking',num(m.maxBankDegrees,1),'°'),metric('Custom barriers',num(m.barrierLengthMeters,1),'m'),metric('Fitted pit bays',`${m.pitCapacity} / ${m.pitBoxes}`,'fitted / selected'),metric('Pit track joins',m.pitConnected?'Connected':'Manual'),metric('Pit connectors',num(m.pitConnectionMeters,1),'m'),metric('Placed trees',String(m.trees)),metric('Placed buildings',String(m.buildings)),metric('Building footprints',num(m.buildingFootprintSquareMeters),'m²'),metric('Grass finish',m.grassFinish),metric('Preview weather',m.previewWeather));
    full.append(metric('Road / pit grip',`${num(data.surfaces.roadGrip,2)} / ${num(data.surfaces.pitGrip,2)}`),metric('Flat kerb grip',num(data.surfaces.kerbGrip,2)),metric('Grass grip',num(data.surfaces.grassGrip,2)),metric('Grass drag / dirt',`${num(data.surfaces.grassDrag,3)} / ${num(data.surfaces.grassDirt,2)}`));
    full.append(...data.timing.sectorLengths.map((length,i)=>metric(`Sector ${i+1} length`,num(length,1),'m')));
    $('#elevation-profile').innerHTML=profile(data.closed&&data.samples.length?[...data.samples,{...data.samples[0],distance:m.lengthMeters}]:data.samples);
    const checks=$('#analysis-checks');checks.replaceChildren();const entries=[...check.errors.map(text=>({text,level:'error'})),...check.warnings.map(text=>({text,level:'warning'}))];if(ready)entries.unshift({text:'Geometry and package requirements met.',level:'pass'});entries.forEach(item=>{const p=document.createElement('p');p.className='analysis-check '+item.level;p.textContent=item.text;checks.append(p);});
    $('#use-pit-capacity').hidden=!(m.pitCapacity>0&&m.pitBoxes>m.pitCapacity);
    const metadata=$('#analysis-profile-data');metadata.replaceChildren();[['Name',t.name==='Untitled Circuit'?'Add a distinctive name':t.name],['Creator',t.export?.author||'Not set'],['Location',[t.export?.city,t.export?.country].filter(Boolean).join(', ')||'Not set'],['Description',t.details?.description?'Provided':'Not added'],['Mod version',t.details?.version||'1.0'],['Reference scale',data.scale.source==='manual'?'Manually entered; calibrate if needed':data.scale.source==='map'?'Calculated from satellite latitude & zoom':'Calibrated with a known distance']].forEach(([label,value])=>{const p=document.createElement('p'),b=document.createElement('b');b.textContent=label+': ';p.append(b,document.createTextNode(value));metadata.append(p);});
    const corners=$('#analysis-corners');corners.replaceChildren();if(!data.corners.length){const p=document.createElement('p');p.className='field-hint';p.textContent='No bends meet the current geometric threshold. Add or refine your road points.';corners.append(p);}data.corners.forEach(c=>{const b=document.createElement('button');b.className='corner-row';b.textContent=`${c.name||'C'+c.number} · ${c.direction} · radius ${num(c.radius,1)} m · ${num(c.angle)}° · ${num(c.length)} m`;b.onclick=()=>{dialog.close();api.focusProgress(c.progress);};corners.append(b);});
  }
  function refresh(){const key=JSON.stringify(api.getTrack());if(key===lastKey)return;lastKey=key;clearTimeout(timer);timer=setTimeout(render,120);}
  const open=()=>{api.editView();clearTimeout(timer);render();dialog.showModal();};$('#open-analysis').onclick=open;$('#analysis-mode').onclick=open;
  $('#analysis-overlay').onchange=()=>api.setOverlay($('#analysis-overlay').checked);$('#reverse-circuit').onclick=()=>api.reverseCircuit();
  $('#analysis-inspect').onclick=()=>{dialog.close();api.preview();};$('#edit-analysis-details').onclick=()=>{dialog.close();$('#circuit-details-btn').click();};
  $('#use-pit-capacity').onclick=()=>{const capacity=analyzeTrack(api.getTrack()).metrics.pitCapacity;if(capacity>0){api.updateTrack(t=>t.export={...t.export,pitboxes:capacity});clearTimeout(timer);render();}};
  $('#analysis-json').onclick=()=>{const data=report();download(`${trackSlug(api.getTrack().name)}_analysis.json`,JSON.stringify(data,null,2),'application/json');};
  $('#analysis-csv').onclick=()=>{const data=report(),s=data.scale.metersPerPixel,header='distance_m,progress,x_m,z_m,elevation_m,grade_percent,bank_degrees,radius_m,section';const rows=data.samples.map(r=>[r.distance,r.progress,(r.x-500)*s,(r.y-370)*s,r.elevation,r.grade,r.bank,r.radius??'',r.kind].map(v=>typeof v==='number'?v.toFixed(5):v).join(','));download(`${trackSlug(api.getTrack().name)}_samples.csv`,[header,...rows].join('\n'),'text/csv');};
  render();return {refresh};
}
